ProgressCb = Callable[[dict[str, Any]], None]

# Keep finished jobs around for polling/SSE reconnects, then prune.
_JOB_TTL_S = 3600.0
_MAX_JOBS = 64
# Local GPU engine: serialize heavy pipelines by default to avoid VRAM thrash / OOM.
# Override with TRANSUB_MAX_CONCURRENT_JOBS (1–8) for CPU-only or multi-GPU hosts.
_MAX_CONCURRENT_JOBS = 1


def _default_max_concurrent_jobs() -> int:
    import os

    raw = str(os.environ.get("TRANSUB_MAX_CONCURRENT_JOBS") or "").strip()
    if not raw:
        return _MAX_CONCURRENT_JOBS
    try:
        return max(1, min(8, int(raw)))
    except (TypeError, ValueError):
        return _MAX_CONCURRENT_JOBS


def _normalize_perf_profile(raw: Any) -> str:
    """Return ``speed`` or ``quality`` (default)."""
    val = str(raw or "").strip().lower()
    if val in ("speed", "fast", "quick"):
        return "speed"
    return "quality"


class JobCancelled(RuntimeError):
    """Raised when a job cooperative-cancel is observed mid-pipeline."""

    def __init__(self, message: str = "cancelled") -> None:
        super().__init__(message)


@dataclass
class JobState:
    id: str
    status: str = "queued"
    request: dict[str, Any] = field(default_factory=dict)
    result: dict[str, Any] | None = None
    error: dict[str, Any] | None = None
    events: list[dict[str, Any]] = field(default_factory=list)
    cancelled: bool = False
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)
    _subprocs: list[Any] = field(default_factory=list)
    _subprocs_lock: threading.Lock = field(default_factory=threading.Lock)
    _events_lock: threading.Lock = field(default_factory=threading.Lock)

    def push(self, event: dict[str, Any]) -> None:
        payload = {"ts": time.time(), **event}
        with self._events_lock:
            self.events.append(payload)
        self.updated_at = time.time()

    def register_subprocess(self, proc: Any) -> None:
        with self._subprocs_lock:
            self._subprocs.append(proc)

    def kill_subprocesses(self, *, reason: str = "cancel") -> None:
        from .proc_util import kill_process_tree

        with self._subprocs_lock:
            procs = list(self._subprocs)
            self._subprocs.clear()
        for proc in procs:
            try:
                kill_process_tree(proc, reason=reason)
            except Exception:
                pass


class JobManager:
    def __init__(self, *, max_concurrent: int = _MAX_CONCURRENT_JOBS) -> None:
        self._jobs: dict[str, JobState] = {}
        self._lock = threading.Lock()
        self._run_sem = threading.Semaphore(max(1, int(max_concurrent)))

    def create(self, request: dict[str, Any], *, run_async: bool = True) -> JobState:
        job_id = uuid.uuid4().hex[:12]
        job = JobState(id=job_id, request=dict(request or {}))
        with self._lock:
            self._prune_locked()
            self._jobs[job_id] = job
        self._persist(job)
        if run_async:
            threading.Thread(target=self._run_job, args=(job_id,), daemon=True).start()
        else:
            self._run_job(job_id)
        return job

    def get(self, job_id: str) -> JobState | None:
        with self._lock:
            hit = self._jobs.get(job_id)
        if hit:
            return hit
        # Restart-friendly: terminal snapshot from disk (status only)
        try:
            from .job_store import load_job_snapshot

            snap = load_job_snapshot(job_id)
            if not snap:
                return None
            restored = JobState(
                id=job_id,
                status=str(snap.get("status") or "error"),
                request=dict(snap.get("request") or {}),
                error=snap.get("error") if isinstance(snap.get("error"), dict) else None,
            )
            restored.created_at = float(snap.get("createdAt") or restored.created_at)
            restored.updated_at = float(snap.get("updatedAt") or restored.updated_at)
            if isinstance(snap.get("resultSummary"), dict):
                restored.result = {
                    "task": snap["resultSummary"].get("task"),
                    "outputs": snap["resultSummary"].get("outputs"),
                    "mtModel": snap["resultSummary"].get("mtModel"),
                    "language": snap["resultSummary"].get("language"),
                    "persisted": True,
                }
            with self._lock:
                self._jobs[job_id] = restored
            return restored
        except Exception:
            return None

    def cancel(self, job_id: str) -> bool:
        job = self.get(job_id)
        if not job:
            return False
        already = bool(job.cancelled)
        job.cancelled = True
        # Kill Demucs / SenseVoice / other child processes immediately.
        try:
            job.kill_subprocesses(reason="job_cancel")
        except Exception:
            pass
        # Mark terminal ASAP so HTTP pollers (waitJob) can exit without waiting
        # for blocking FunASR.generate() to finish.
        if job.status in ("queued", "running"):
            job.status = "cancelled"
            job.error = {"code": "CANCELLED", "message": "cancelled"}
        if not already:
            job.push({"type": "progress", "stage": "cancel", "detail": "已请求取消"})
            job.push({"type": "error", "code": "CANCELLED", "message": "cancelled"})
        self._persist(job)
        return True

    def resume(
        self,
        job_id: str,
        *,
        run_async: bool = True,
        overrides: dict[str, Any] | None = None,
    ) -> JobState:
        """
        Create a new job that continues from a checkpoint of ``job_id``.

        Requires ``{job_id}.ckpt.json`` with at least ``asr_done`` (source cues).
        Optional ``overrides`` (e.g. fresh ``mtExternal`` URL) are merged after
        the checkpoint request so desktop adapters can rebind on resume.
        """
        from .checkpoint import build_resume_request, load_checkpoint

        ckpt = load_checkpoint(job_id)
        if not ckpt or not (ckpt.get("sourceCues") or []):
            raise FileNotFoundError(
                f"no resumable checkpoint for job {job_id} "
                "(need asr_done with source cues)"
            )
        req = build_resume_request(ckpt)
        # Prefer media path from original request; checkpoint already embeds it
        if not req.get("mediaPath"):
            snap_job = self.get(job_id)
            if snap_job and snap_job.request.get("mediaPath"):
                req["mediaPath"] = snap_job.request["mediaPath"]
        if isinstance(overrides, dict) and overrides:
            # Keep _checkpoint from build_resume_request; allow MT/output rebinding.
            ckpt_blob = req.get("_checkpoint")
            req.update({k: v for k, v in overrides.items() if k != "_checkpoint"})
            if ckpt_blob is not None:
                req["_checkpoint"] = ckpt_blob
        return self.create(req, run_async=run_async)

    def create_batch(
        self,
        requests: list[dict[str, Any]],
        *,
        batch_id: str | None = None,
        run_async: bool = True,
    ) -> tuple[str, list[JobState]]:
        """Enqueue many jobs; they share the process semaphore (serialized GPU)."""
        from .batch import build_batch_requests

        paths = [str(r.get("mediaPath") or "") for r in requests]
        bid, reqs = build_batch_requests(
            paths,
            template={},
            batch_id=batch_id,
            per_item=list(requests),
        )
        jobs: list[JobState] = []
        for req in reqs:
            jobs.append(self.create(req, run_async=run_async))
        return bid, jobs

    def get_batch_summary(self, batch_id: str) -> dict[str, Any]:
        from .batch import summarize_batch
        from .job_store import list_job_snapshots

        bid = str(batch_id or "").strip()
        if not bid:
            raise ValueError("batchId required")
        found: list[Any] = []
        seen: set[str] = set()
        with self._lock:
            for job in self._jobs.values():
                if str((job.request or {}).get("batchId") or "") == bid:
                    found.append(job)
                    seen.add(job.id)
        for row in list_job_snapshots(limit=200):
            jid = str(row.get("id") or "")
            if jid in seen:
                continue
            req = row.get("request") or {}
            if str(req.get("batchId") or "") == bid:
                found.append(row)
                seen.add(jid)
        if not found:
            raise FileNotFoundError(f"batch not found: {bid}")
        return summarize_batch(bid, found)

    def _persist(self, job: JobState) -> None:
        try:
            from .job_store import save_job_snapshot

            save_job_snapshot(job)
        except Exception:
            pass

    def _prune_locked(self) -> None:
        """Drop old terminal jobs; must hold self._lock."""
        from .job_store import delete_job_snapshot

        now = time.time()
        terminal = ("done", "error", "cancelled")
        stale = [
            jid
            for jid, job in self._jobs.items()
            if job.status in terminal and (now - float(job.updated_at or job.created_at)) > _JOB_TTL_S
        ]
        for jid in stale:
            self._jobs.pop(jid, None)
            try:
                delete_job_snapshot(jid)
            except Exception:
                pass
            try:
                from .checkpoint import delete_checkpoint

                delete_checkpoint(jid)
            except Exception:
                pass
        if len(self._jobs) <= _MAX_JOBS:
            return
        # Evict oldest terminal jobs first
        terminal_jobs = sorted(
            (
                (float(job.updated_at or job.created_at), jid)
                for jid, job in self._jobs.items()
                if job.status in terminal
            ),
            key=lambda x: x[0],
        )
        overflow = len(self._jobs) - _MAX_JOBS
        for _, jid in terminal_jobs[: max(0, overflow)]:
            self._jobs.pop(jid, None)
            try:
                delete_job_snapshot(jid)
            except Exception:
                pass
            try:
                from .checkpoint import delete_checkpoint

                delete_checkpoint(jid)
            except Exception:
                pass

    def _mark_cancelled(self, job: JobState, *, push_event: bool = False) -> None:
        job.status = "cancelled"
        job.error = {"code": "CANCELLED", "message": "cancelled"}
        if push_event:
            # Avoid duplicate CANCELLED when cancel() already pushed one.
            has_cancel_err = any(
                ev.get("type") == "error" and ev.get("code") == "CANCELLED" for ev in job.events
            )
            if not has_cancel_err:
                job.push({"type": "error", "code": "CANCELLED", "message": "cancelled"})
        self._persist(job)

    def _run_job(self, job_id: str) -> None:
        job = self.get(job_id)
        if not job:
            return
        if job.cancelled:
            self._mark_cancelled(job, push_event=True)
            return
        acquired = self._run_sem.acquire(blocking=True)
        try:
            if job.cancelled:
                self._mark_cancelled(job, push_event=True)
                return
            job.status = "running"
            self._persist(job)
            try:
                result = execute_job(job.request, job=job)
                if job.cancelled:
                    self._mark_cancelled(job, push_event=True)
                    return
                job.result = result
                job.status = "done"
                job.push({"type": "done", "ok": True, "result": result})
                self._persist(job)
            except JobCancelled:
                self._mark_cancelled(job, push_event=True)
            except Exception as err:
                # Progress / preprocess may raise bare RuntimeError("cancelled")
                if job.cancelled or _is_cancel_message(err):
                    self._mark_cancelled(job, push_event=True)
                    return
                import traceback
                import sys

                tb = traceback.format_exc()
                # QC 局部重转写等短窗常见「空结果」：只打一行，避免整段 Traceback 吓到用户
                msg = str(err or "")
                soft_empty = (
                    "未识别到有效字幕" in msg
                    or ("结果为空" in msg and "SenseVoice" in msg)
                )
                try:
                    if soft_empty:
                        print(f"[engine] ASR 空结果（已跳过）: {msg}", flush=True)
                    else:
                        print(tb, flush=True)
                except UnicodeEncodeError:
                    enc = getattr(sys.stdout, "encoding", None) or "utf-8"
                    line = (f"[engine] ASR 空结果（已跳过）: {msg}\n" if soft_empty else tb + "\n")
                    sys.stdout.buffer.write(line.encode(enc, errors="replace"))
                    sys.stdout.flush()
                code = getattr(err, "code", None)
                err_code = "ASR_EMPTY" if soft_empty else (str(code) if code else "JOB_FAILED")
                job.status = "error"
                job.error = {
                    "code": err_code,
                    "message": str(err),
                    "traceback": "" if soft_empty else tb,
                }
                job.push({"type": "error", "code": err_code, "message": str(err)})
                self._persist(job)
        finally:
            # Reclaim ASR / Demucs / ffmpeg scratch before releasing the run slot.
            try:
                sweep_job_temps()
            except Exception:
                pass
            if acquired:
                self._run_sem.release()


def _is_cancel_message(err: BaseException) -> bool:
    code = str(getattr(err, "code", "") or "")
    if code in ("MT_EXTERNAL_CANCELLED", "cancelled", "canceled"):
        return True
    msg = str(err or "").strip().lower()
    if "已取消" in str(err or ""):
        return True
    return (
        msg in ("cancelled", "canceled")
        or msg.endswith("cancelled")
        or msg.endswith("canceled")
        or "external mt cancelled" in msg
    )


def _emit(job: JobState | None, on_progress: ProgressCb | None, event: dict[str, Any]) -> None:
    if job and job.cancelled:
        raise JobCancelled()
    payload = {"type": "progress", **event}
    if job:
        job.push(payload)
    if on_progress:
        on_progress(payload)


def _guess_mt_language(language: str, cues: list[dict[str, Any]]) -> str:
    """Resolve auto language for Opus pair selection from ASR cue scripts."""
    lang = str(language or "auto").strip().lower()
    if lang and lang not in ("auto",):
        return lang
    sample = " ".join(str(c.get("text") or "") for c in (cues or [])[:12])
    if not sample.strip():
        return "en"
    ja = sum(1 for ch in sample if "\u3040" <= ch <= "\u30ff")
    ko = sum(1 for ch in sample if "\uac00" <= ch <= "\ud7af")
    zh = sum(1 for ch in sample if "\u4e00" <= ch <= "\u9fff")
    latin = sum(1 for ch in sample if ("a" <= ch.lower() <= "z"))
    # Hangul / kana are strong signals; Han alone often means Chinese ASR output.
    if ko >= 3 and ko >= ja:
        return "ko"
    if ja >= 3:
        return "ja"
    if zh >= 8 and ja < 2 and ko < 2 and latin < zh:
        return "zh"
    return "en"


def _is_chinese_lang(language: str) -> bool:
    primary = str(language or "").strip().lower().replace("_", "-").split("-", 1)[0]
    return primary in ("zh", "cn", "yue", "chinese", "cantonese")


def execute_job(
    request: dict[str, Any],
    *,
    job: JobState | None = None,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    media = str(request.get("mediaPath") or "").strip()
    if not media:
        raise ValueError("mediaPath is required")
    if not Path(media).exists():
        raise FileNotFoundError(f"media not found: {media}")

    task = str(request.get("task") or "transcribe").strip()
    language = str(request.get("language") or "auto").strip() or "auto"
    asr_model = str(request.get("asrModel") or "sensevoice-small").strip()
    mt_model = request.get("mtModel")
    mt_backend = normalize_mt_backend(
        request.get("mtBackend") or request.get("mt_backend")
    )
    mt_external = request.get("mtExternal") or request.get("mt_external")
    if mt_backend == BACKEND_EXTERNAL and task in ("translate_mt", "dual"):
        from .mt.external_http import normalize_mt_external

        mt_external = normalize_mt_external(mt_external)
    output_dir = Path(str(request.get("outputDir") or Path(media).parent))
    output_dir.mkdir(parents=True, exist_ok=True)
    formats = request.get("subFormats") or ["srt"]
    if isinstance(formats, str):
        formats = [x.strip() for x in formats.split(",") if x.strip()]
    want_dual_ass = bool(request.get("dualAss"))
    norm_formats: list[str] = []
    for f in formats:
        fl = str(f or "").strip().lower()
        if fl in ("ass-dual", "dual-ass", "assb"):
            want_dual_ass = True
            if "ass" not in [x.lower() for x in norm_formats]:
                norm_formats.append("ass")
        elif fl:
            norm_formats.append(fl)
    formats = norm_formats or ["srt"]
    release_gpu_after = bool(
        request.get("releaseGpuAfter") or request.get("release_gpu_after")
    )
    include_words = bool(request.get("includeWords") or request.get("include_words"))
    karaoke_vtt = bool(request.get("karaokeVtt") or request.get("karaoke_vtt"))
    if karaoke_vtt:
        include_words = True
    perf_profile = _normalize_perf_profile(
        request.get("perfProfile") or request.get("perf_profile")
    )
    speed_mode = perf_profile == "speed"
    # wordTimestamps: None → auto (on for quality; off for speed unless words/karaoke)
    word_ts_raw = request.get("wordTimestamps", request.get("word_timestamps", None))
    if include_words:
        word_timestamps: bool | None = True
    elif word_ts_raw is None:
        word_timestamps = False if speed_mode else True
    else:
        word_timestamps = bool(word_ts_raw)
    # anime-whisper / Qwen timing:
    # timingAlign: false / off → rate-repair windows only ("").
    # timingAlignModel: ten|vad|auto|omit → TEN short-frame island ASR (default).
    # timingAlignModel: firered|firered-vad → FireRedVAD island ASR.
    # timingAlignModel: whisper-ja-1.5b|wav2vec2|… → post-hoc dual align.
    timing_align_raw = request.get("timingAlign", request.get("timing_align", None))
    timing_align_model_raw = request.get(
        "timingAlignModel", request.get("timing_align_model", None)
    )
    if timing_align_raw is False or str(timing_align_raw).strip().lower() in (
        "0",
        "false",
        "off",
        "no",
    ):
        timing_align_model: str | None = ""
    elif timing_align_model_raw is not None and str(timing_align_model_raw).strip() != "":
        timing_align_model = str(timing_align_model_raw).strip()
    else:
        timing_align_model = None  # auto → TEN islands for anime-whisper / Qwen
    # Retranscribe suspicious clips (Whisper); default off in speed mode.
    retranscribe_raw = request.get("retranscribe", request.get("clipRetranscribe", None))
    if retranscribe_raw is None:
        enable_retranscribe = not speed_mode
    else:
        enable_retranscribe = bool(retranscribe_raw)
    # anime/kotoba CT2: post-ASR clip retranscribe historically enabled
    # word_timestamps / hallucination_silence and ACCESS_VIOLATION-crashed the
    # engine right after a successful windowed pass — keep it off by default.
    try:
        from .models_catalog import asr_needs_windowed_transcribe as _needs_win_re

        if _needs_win_re(asr_model) and retranscribe_raw is None:
            enable_retranscribe = False
    except Exception:
        pass
    device = str(request.get("device") or "auto")
    vad = request.get("vad") if isinstance(request.get("vad"), dict) else {}
    audio = request.get("audio") if isinstance(request.get("audio"), dict) else {}
    glossary = request.get("glossary")
    asr_glossary = request.get("asrGlossary") or request.get("asr_glossary") or request.get(
        "sourceGlossary"
    ) or request.get("source_glossary")
    cast_names = (
        request.get("castNames")
        or request.get("cast_names")
        or request.get("asrNames")
        or request.get("asr_names")
    )
    initial_prompt = str(
        request.get("initialPrompt") or request.get("initial_prompt") or ""
    ).strip()
    hotwords = str(request.get("hotwords") or request.get("hotWords") or "").strip()
    content_profile = str(
        request.get("contentProfile")
        or request.get("content_profile")
        or request.get("senseProfile")
        or request.get("sense_profile")
        or ""
    ).strip().lower()
    lang_l_early = str(language or "").lower()
    is_ja_lang = lang_l_early.startswith("ja") or lang_l_early in ("japanese", "jp")
    is_av_profile = content_profile in (
        "av_soft",
        "av-soft",
        "ja-av",
        "ja_av",
        "av",
    )
    from .models_catalog import asr_skips_whisper_prompt

    # anime-whisper: any initial_prompt causes severe hallucinations (upstream caveat).
    skip_whisper_prompt = asr_skips_whisper_prompt(asr_model)
    if skip_whisper_prompt:
        initial_prompt = ""
        hotwords = ""
    # Auto-build Whisper name bias from asrGlossary + castNames (+ builtin JA names)
    elif not initial_prompt or not hotwords:
        try:
            from .glossary import names_for_whisper_bias

            auto_prompt, auto_hot = names_for_whisper_bias(
                asr_glossary or [],
                asr_only=True,
                cast_names=cast_names,
            )
            # JA: always strengthen with 舞/トミー + common given-name bias
            if is_ja_lang and request.get(
                "builtinNames", request.get("builtin_names", True)
            ):
                from .mt.ja_names import ja_whisper_name_bias

                bias_prompt, bias_hot = ja_whisper_name_bias(cast_names=cast_names)
                if bias_prompt:
                    if not auto_prompt:
                        auto_prompt = bias_prompt
                    elif "舞" not in auto_prompt:
                        # Prepend priority cast hint without dropping user glossary bias
                        auto_prompt = bias_prompt.rstrip("。") + "。" + auto_prompt
                if bias_hot:
                    hot_parts = []
                    seen_h: set[str] = set()
                    for part in (bias_hot + " " + (auto_hot or "")).split():
                        if part and part not in seen_h:
                            seen_h.add(part)
                            hot_parts.append(part)
                    auto_hot = " ".join(hot_parts)
            # Soft-AV domain vocabulary — ONLY when content profile is AV.
            # Applying to all JA polluted drama (JUR-809 / HMN-869) with term spam.
            if is_av_profile:
                try:
                    from .cue_cleanup import ja_av_domain_whisper_bias

                    media_hint = " ".join(
                        str(request.get(k) or "")
                        for k in (
                            "mediaPath",
                            "media_path",
                            "inputPath",
                            "input_path",
                            "title",
                            "outputPath",
                            "output_path",
                        )
                    )
                    dom_prompt, dom_hot = ja_av_domain_whisper_bias(hint=media_hint)
                    if dom_prompt:
                        if not auto_prompt:
                            auto_prompt = dom_prompt
                        elif "メンズエステ" not in auto_prompt and "メンエス" not in auto_prompt:
                            # Generic soft-AV prompt also skips when already present
                            if "自然な会話" not in auto_prompt:
                                auto_prompt = dom_prompt.rstrip("。") + "。" + auto_prompt
                    if dom_hot:
                        hot_parts = []
                        seen_h: set[str] = set()
                        for part in ((auto_hot or "") + " " + dom_hot).split():
                            if part and part not in seen_h:
                                seen_h.add(part)
                                hot_parts.append(part)
                        auto_hot = " ".join(hot_parts)
                except Exception:
                    pass
            if not initial_prompt:
                initial_prompt = auto_prompt
            if not hotwords:
                hotwords = auto_hot
        except Exception:
            pass
    # Even when caller supplied prompt/hotwords, append domain bias only for av_soft
    elif is_av_profile and not skip_whisper_prompt:
        try:
            from .cue_cleanup import ja_av_domain_whisper_bias

            media_hint = " ".join(
                str(request.get(k) or "")
                for k in (
                    "mediaPath",
                    "media_path",
                    "inputPath",
                    "input_path",
                    "title",
                    "outputPath",
                    "output_path",
                )
            )
            dom_prompt, dom_hot = ja_av_domain_whisper_bias(hint=media_hint)
            esthe_or_generic = (
                "メンズエステ" not in initial_prompt
                and "メンエス" not in initial_prompt
                and "自然な会話" not in initial_prompt
            )
            if dom_prompt and esthe_or_generic:
                initial_prompt = (dom_prompt.rstrip("。") + "。" + initial_prompt).strip()
            if dom_hot:
                hot_parts = []
                seen_h: set[str] = set()
                for part in (hotwords + " " + dom_hot).split():
                    if part and part not in seen_h:
                        seen_h.add(part)
                        hot_parts.append(part)
                hotwords = " ".join(hot_parts)
        except Exception:
            pass
    film_audio = bool(audio.get("filmAudioEnhance") or audio.get("filmPreset"))
    if audio.get("filmAudioEnhance"):
        audio = {**audio, "separate": True, "filmPreset": True}
        film_audio = True

    try:
        _off = audio.get("startSec")
        if _off is None:
            _off = audio.get("trimStartSec")
        if _off is None:
            _off = audio.get("start_sec")
        media_time_offset = float(_off or 0)
    except (TypeError, ValueError):
        media_time_offset = 0.0
    if media_time_offset < 0:
        media_time_offset = 0.0

    beam_raw = request.get("beamSize", request.get("beam_size"))
    beam_size: int | None = None
    if beam_raw is not None and str(beam_raw).strip() != "":
        try:
            beam_size = max(1, min(20, int(float(beam_raw))))
        except (TypeError, ValueError):
            beam_size = None
    elif speed_mode:
        beam_size = 1

    vad_opts = normalize_vad_options(vad, film_preset=film_audio)
    vad_model = str(vad_opts.get("model") or "").strip()
    try:
        from .models_catalog import resolve_asr_backend

        is_whisper = resolve_asr_backend(asr_model) == "whisper"
    except Exception:
        is_whisper = "whisper" in asr_model
    if is_whisper and vad_opts.get("sensitive"):
        vad_model = "whisperseg-asmr"
    if not vad_model:
        vad_model = (
            DEFAULT_VAD_FOR_WHISPER if is_whisper else DEFAULT_VAD_FOR_SENSEVOICE
        )
    vad_opts["model"] = vad_model

    # Selecting FireRed as catalog VAD steers anime/Qwen island timing when
    # timingAlignModel is still auto/default (does not override explicit TEN/aligner).
    vad_l_early = str(vad_model or "").strip().lower()
    if "firered" in vad_l_early and timing_align_model is None:
        timing_align_model = "firered"

    # Fail fast when Opus MT is clearly required but missing (avoid hours of ASR first).
    if task in ("translate_mt", "dual") and mt_backend != BACKEND_EXTERNAL:
        from .download import is_model_installed

        explicit_mt = str(mt_model).strip() if mt_model else ""
        lang_for_mt = str(language or "").strip().lower()
        if explicit_mt:
            if not is_model_installed(explicit_mt):
                raise RuntimeError(
                    f"未安装翻译模型 {explicit_mt}。"
                    f"请在「设置 → 环境 / 模型」下载后再开始生成。"
                )
        elif lang_for_mt and lang_for_mt not in ("auto", ""):
            mid = pick_mt_model(lang_for_mt, None)
            if mid and not is_model_installed(mid):
                raise RuntimeError(
                    f"未安装翻译模型 {mid}（语种 {lang_for_mt}）。"
                    f"请在「设置 → 环境 / 模型」下载后再开始生成。"
                )

    # JA translate/dual + Whisper: default to WhisperSeg unless user explicitly
    # opted into Silero/FSMN with sensitive=false (covers API jobs that omit vad).
    # Speed profile skips this and keeps Silero (or explicit vad.model).
    lang_l = str(language or "").strip().lower()
    is_ja_lang = lang_l.startswith("ja") or lang_l in ("japanese", "jp")
    if (
        is_whisper
        and is_ja_lang
        and task in ("translate_mt", "dual")
        and not speed_mode
    ):
        vad_raw = request.get("vad") if isinstance(request.get("vad"), dict) else None
        raw_model = str((vad_raw or {}).get("model") or "").strip().lower()
        # Silero is the only explicit Whisper opt-out; fsmn is SenseVoice default.
        explicit_non_seg = raw_model in ("silero-vad", "silero") and not bool(
            (vad_raw or {}).get("sensitive")
        )
        if not explicit_non_seg:
            merged_vad = {
                **(vad_raw or {}),
                "sensitive": True,
                "model": "whisperseg-asmr",
            }
            vad_opts = normalize_vad_options(merged_vad, film_preset=film_audio)
            vad_model = "whisperseg-asmr"
            vad_opts["model"] = vad_model
            vad_opts["sensitive"] = True
    elif speed_mode and is_whisper and is_ja_lang:
        # Prefer lighter Silero unless caller already chose WhisperSeg.
        vad_raw = request.get("vad") if isinstance(request.get("vad"), dict) else None
        raw_model = str((vad_raw or {}).get("model") or "").strip().lower()
        if "whisperseg" not in raw_model and not bool((vad_raw or {}).get("sensitive")):
            if vad_model == "whisperseg-asmr" or not raw_model:
                vad_model = DEFAULT_VAD_FOR_WHISPER
                vad_opts["model"] = vad_model
                vad_opts["sensitive"] = False

    def progress(ev: dict[str, Any]) -> None:
        from .progress import remap_job_progress

        _emit(job, on_progress, remap_job_progress(task, ev if isinstance(ev, dict) else {}))

    ckpt_in = request.get("_checkpoint") if isinstance(request.get("_checkpoint"), dict) else None
    resume_stage = str((ckpt_in or {}).get("stage") or "")
    resume_source = list((ckpt_in or {}).get("sourceCues") or [])
    resume_zh = (ckpt_in or {}).get("zhCues")
    can_skip_asr = resume_stage in ("asr_done", "mt_done") and bool(resume_source)
    can_skip_mt = resume_stage == "mt_done" and isinstance(resume_zh, list)

    if can_skip_asr:
        progress(
            {
                "stage": "starting",
                "percent": 5,
                "detail": f"从断点恢复（{resume_stage}，{len(resume_source)} 条）",
            }
        )
    else:
        progress({"stage": "starting", "percent": 1, "detail": "任务已启动"})

    import os

    from .ffmpeg_util import ensure_ffmpeg_on_path

    ffmpeg_path = str(request.get("ffmpegPath") or "").strip()
    if ffmpeg_path:
        os.environ["FFMPEG_BINARY"] = ffmpeg_path
        os.environ["FFMPEG_PATH"] = ffmpeg_path
        ffmpeg_dir = str(Path(ffmpeg_path).parent)
        path_env = os.environ.get("PATH", "")
        if ffmpeg_dir and ffmpeg_dir not in path_env.split(os.pathsep):
            os.environ["PATH"] = ffmpeg_dir + os.pathsep + path_env
    ensure_ffmpeg_on_path()

    temps: list[str] = []
    asr_media = media
    clip_timestamps: list[dict[str, float]] | None = None
    force_no_vad = False
    use_whisperseg = False
    source_cues: list[dict[str, Any]] = []
    stream_writers: list[StreamingSubtitleWriter] = []

    if can_skip_asr:
        source_cues = [dict(c) for c in resume_source if isinstance(c, dict)]
    else:
        try:
            asr_media, temps = preprocess_media(
                media,
                audio,
                device=device,
                on_progress=lambda e: progress(e),
                should_cancel=lambda: bool(job and job.cancelled),
                register_subprocess=(job.register_subprocess if job else None),
            )

            use_whisperseg = (
                is_whisper and vad_model == "whisperseg-asmr" and vad_opts.get("enabled", True)
            )
            # anime-whisper: WhisperSeg / Silero clip gating drops most spoken dialogue
            # on soft-AV. Always decode crash-safe fixed windows over the full timeline.
            # kotoba still uses WhisperSeg when enabled; windowing alone prevents CT2 crash.
            try:
                from .models_catalog import asr_skips_whisperseg_gating

                skip_seg_gating = asr_skips_whisperseg_gating(asr_model)
            except Exception:
                skip_seg_gating = "anime-whisper" in str(asr_model or "").lower()
            if skip_seg_gating:
                if use_whisperseg:
                    use_whisperseg = False
                    progress(
                        {
                            "stage": "vad",
                            "percent": 8,
                            "detail": "anime-whisper · 定长全片分窗（跳过 WhisperSeg，避免丢对白）",
                        }
                    )
                force_no_vad = True
                clip_timestamps = None
            # SenseVoice only accepts FunASR fsmn-vad (not WhisperSeg / Silero / FireRed).
            # Do not coerce for Qwen / Parakeet / Cohere / Reazon — FireRed is their timing VAD.
            asr_backend = ""
            try:
                asr_backend = resolve_asr_backend(asr_model)
            except Exception:
                asr_backend = "whisper" if is_whisper else ""
            if asr_backend == "sensevoice":
                vad_l = str(vad_model or "").strip().lower()
                if vad_l == "whisperseg-asmr" or "whisperseg" in vad_l:
                    progress(
                        {
                            "stage": "vad",
                            "percent": 3,
                            "detail": "SenseVoice 不支持 WhisperSeg · 回退 fsmn-vad（灵敏检出请改用 Whisper ASR）",
                        }
                    )
                    vad_model = "fsmn-vad"
                    vad_opts = {**vad_opts, "model": vad_model, "sensitive": False}
                elif vad_l in ("silero-vad", "silero") or vad_l.startswith("silero"):
                    progress(
                        {
                            "stage": "vad",
                            "percent": 3,
                            "detail": "SenseVoice 不支持 Silero VAD · 回退 fsmn-vad",
                        }
                    )
                    vad_model = "fsmn-vad"
                    vad_opts = {**vad_opts, "model": vad_model, "sensitive": False}
                elif "firered" in vad_l:
                    progress(
                        {
                            "stage": "vad",
                            "percent": 3,
                            "detail": "SenseVoice 不支持 FireRedVAD · 回退 fsmn-vad（FireRed 用于 anime/Qwen 时间轴）",
                        }
                    )
                    vad_model = "fsmn-vad"
                    vad_opts = {**vad_opts, "model": vad_model, "sensitive": False}
            elif "firered" in str(vad_model or "").lower() and asr_backend in (
                "qwen3-asr",
                "whisper",
                "parakeet",
                "cohere-asr",
                "reazon-k2",
            ):
                # Catalog VAD already mapped to timingAlignModel=firered above.
                if asr_backend != "whisper":
                    progress(
                        {
                            "stage": "vad",
                            "percent": 3,
                            "detail": "FireRedVAD · 时间轴短帧（anime/Qwen）",
                        }
                    )
            if use_whisperseg:
                from .asr.whisper_fw import _probe_duration_s
                from .audio.scene_split import detect_coarse_scenes
                from .vad.whisperseg import run_whisperseg_clips, should_force_full_transcribe

                duration_s = _probe_duration_s(asr_media)
                scenes = detect_coarse_scenes(
                    asr_media,
                    duration_s=duration_s,
                    on_progress=lambda e: progress(e),
                )
                try:
                    clips = run_whisperseg_clips(
                        asr_media,
                        vad_options=vad_opts,
                        scenes=scenes if len(scenes) > 1 else None,
                        device=device,
                        on_progress=lambda e: progress(e),
                    )
                except JobCancelled:
                    raise
                except Exception as err:
                    if _is_cancel_message(err):
                        raise JobCancelled() from err
                    raise RuntimeError(str(err)) from err

                if clips and not should_force_full_transcribe(
                    clips, duration_s=duration_s
                ):
                    clip_timestamps = clips
                elif should_force_full_transcribe(clips or [], duration_s=duration_s):
                    # Sparse / empty WhisperSeg: anime-whisper uses fixed windows;
                    # other Whisper models decode full audio without Silero re-filter.
                    force_no_vad = True
                    clip_timestamps = None
                    spoken = sum(
                        max(0.0, float(c["end"]) - float(c["start"]))
                        for c in (clips or [])
                    )
                    ratio = (spoken / duration_s) if duration_s > 0 else 0.0
                    progress(
                        {
                            "stage": "vad_failover",
                            "percent": 20,
                            "detail": (
                                "WhisperSeg 无结果 · 回退全片音频"
                                if not clips
                                else (
                                    f"WhisperSeg 过稀（人声约 {ratio:.1%}）"
                                    " · 回退全片/定长分段"
                                )
                            ),
                        }
                    )
                else:
                    progress(
                        {
                            "stage": "vad",
                            "percent": 18,
                            "detail": "WhisperSeg 无结果 · 回退 Silero",
                        }
                    )

            # previewStreaming: Player-only. Early first SRT flush (+ stream non-Whisper).
            # Transub batch jobs omit the flag → same 32-cue stride / Whisper-only writers.
            preview_streaming = bool(
                request.get("previewStreaming") or request.get("preview_streaming")
            )
            on_cue = None
            if (is_whisper or preview_streaming) and task in ("transcribe", "dual"):
                stem_early = Path(media).stem
                for fmt in formats:
                    name = (
                        f"{stem_early}.{fmt}"
                        if task == "transcribe"
                        else f"{stem_early}.src.{fmt}"
                    )
                    stream_writers.append(
                        StreamingSubtitleWriter(
                            output_dir / name,
                            fmt=fmt,
                            preview_streaming=preview_streaming,
                        )
                    )

                def _on_cue(cue: dict[str, Any]) -> None:
                    if media_time_offset:
                        cue = {
                            **cue,
                            "start": float(cue.get("start") or 0) + media_time_offset,
                            "end": float(cue.get("end") or 0) + media_time_offset,
                        }
                        words = cue.get("words")
                        if isinstance(words, list):
                            cue["words"] = [
                                {
                                    **w,
                                    "start": float(w.get("start") or 0) + media_time_offset,
                                    "end": float(w.get("end") or 0) + media_time_offset,
                                }
                                if isinstance(w, dict)
                                else w
                                for w in words
                            ]
                    for w in stream_writers:
                        w.append(cue)

                on_cue = _on_cue

            source_cues = run_asr(
                media_path=asr_media,
                language=language,
                asr_model=asr_model,
                vad_model=vad_model,
                vad_options=vad_opts,
                device=device,
                beam_size=beam_size,
                clip_timestamps=clip_timestamps,
                force_no_vad=force_no_vad,
                initial_prompt=initial_prompt or None,
                hotwords=hotwords or None,
                on_progress=lambda e: progress(e),
                on_cue=on_cue,
                should_cancel=lambda: bool(job and job.cancelled),
                register_subprocess=(job.register_subprocess if job else None),
                include_words=include_words,
                word_timestamps=word_timestamps,
                force_inprocess=bool(
                    request.get("sensevoiceInprocess")
                    or request.get("sensevoice_inprocess")
                ),
                timing_align_model=timing_align_model,
            )
            if media_time_offset and source_cues:
                shifted: list[dict[str, Any]] = []
                for cue in source_cues:
                    if not isinstance(cue, dict):
                        continue
                    item = {
                        **cue,
                        "start": float(cue.get("start") or 0) + media_time_offset,
                        "end": float(cue.get("end") or 0) + media_time_offset,
                    }
                    words = cue.get("words")
                    if isinstance(words, list):
                        item["words"] = [
                            {
                                **w,
                                "start": float(w.get("start") or 0) + media_time_offset,
                                "end": float(w.get("end") or 0) + media_time_offset,
                            }
                            if isinstance(w, dict)
                            else w
                            for w in words
                        ]
                    shifted.append(item)
                source_cues = shifted
            for w in stream_writers:
                try:
                    w.close()
                except Exception:
                    pass

            lang_l = str(language or "").strip().lower()
            # language=auto is common; still treat soft-AV profile / anime ASR as ja_av
            # so collapsed-TS CPS keep rules and moan-safe cleanup apply.
            try:
                from .models_catalog import asr_is_anime_whisper as _is_anime_asr
            except Exception:
                def _is_anime_asr(_m: str | None) -> bool:  # type: ignore[misc]
                    return "anime-whisper" in str(_m or "").lower()

            ja_av = (
                use_whisperseg
                or is_av_profile
                or lang_l in ("ja", "japanese", "jp")
                or _is_anime_asr(asr_model)
            )
            film_mode = bool(vad_opts.get("filmPreset"))
            # Always strip symbol-only / ▁ / Latin spacing junk; JA AV adds soft-scene rules.
            try:
                from .cue_cleanup import clean_cues

                before_n = len(source_cues or [])
                source_cues = clean_cues(source_cues, ja_av=ja_av)
                dropped = before_n - len(source_cues)
                if dropped > 0:
                    progress(
                        {
                            "stage": "cleanup",
                            "percent": 88,
                            "detail": (
                                f"日语 清理 · 去掉 {dropped} 条"
                                if ja_av
                                else f"ASR 清理 · 去掉 {dropped} 条"
                            ),
                        }
                    )
            except Exception:
                pass

            if is_whisper and clip_timestamps and enable_retranscribe:
                try:
                    from .retranscribe import retranscribe_bad_clips

                    source_cues, n_retry = retranscribe_bad_clips(
                        media_path=asr_media,
                        cues=source_cues,
                        clips=clip_timestamps,
                        language=language,
                        asr_model=asr_model,
                        device=device,
                        beam_size=beam_size,
                        vad_options=vad_opts,
                        initial_prompt=initial_prompt or None,
                        hotwords=hotwords or None,
                        on_progress=lambda e: progress(e),
                        should_cancel=lambda: bool(job and job.cancelled),
                        ja_av=ja_av,
                    )
                    if n_retry > 0:
                        progress(
                            {
                                "stage": "transcribe",
                                "percent": 91,
                                "detail": f"已重转写 {n_retry} 个可疑片段",
                            }
                        )
                        if ja_av or film_mode:
                            from .cue_cleanup import clean_cues

                            source_cues = clean_cues(source_cues, ja_av=ja_av)
                        for w in stream_writers:
                            try:
                                w.replace_all(source_cues)
                            except Exception:
                                pass
                except JobCancelled:
                    raise
                except Exception as err:
                    if _is_cancel_message(err):
                        raise JobCancelled() from err

            try:
                from .quality import (
                    filter_hallucinated_cues,
                    filter_low_confidence_cues,
                    merge_timeline_cues,
                )

                lang_l = str(language or "").strip().lower()
                ja_av = (
                    use_whisperseg
                    or is_av_profile
                    or lang_l in ("ja", "japanese", "jp")
                    or _is_anime_asr(asr_model)
                )
                film_mode = bool(vad_opts.get("filmPreset"))
                source_cues, hallu_dropped = filter_hallucinated_cues(
                    source_cues, ja_av=ja_av
                )
                source_cues, conf_dropped = filter_low_confidence_cues(
                    source_cues, ja_av=ja_av, film=film_mode
                )
                before_merge = len(source_cues)
                source_cues = merge_timeline_cues(source_cues)
                merged_n = max(0, before_merge - len(source_cues))
                dropped_total = hallu_dropped + conf_dropped
                if dropped_total > 0 or merged_n > 0:
                    detail_parts = []
                    if hallu_dropped:
                        detail_parts.append(f"循环幻觉 {hallu_dropped}")
                    if conf_dropped:
                        detail_parts.append(f"低置信 {conf_dropped}")
                    if merged_n:
                        detail_parts.append(f"合并 {merged_n}")
                    if ja_av:
                        detail_parts.append("日语")
                    elif film_mode:
                        detail_parts.append("影视")
                    progress(
                        {
                            "stage": "cleanup",
                            "percent": 89,
                            "detail": "质量清理 · " + " · ".join(detail_parts),
                        }
                    )
                    for w in stream_writers:
                        try:
                            w.replace_all(source_cues)
                        except Exception:
                            pass
            except Exception:
                pass

            # ASR-side glossary: misheard → correct on source cues (names etc.)
            try:
                from .glossary import apply_asr_glossary_to_cues

                gloss_hits = 0
                asr_for_apply = asr_glossary
                if str(language or "").lower().startswith("ja") and request.get(
                    "builtinNames", request.get("builtin_names", True)
                ):
                    try:
                        from .mt.ja_names import merge_asr_name_glossary

                        asr_for_apply = merge_asr_name_glossary(asr_glossary)
                    except Exception:
                        asr_for_apply = asr_glossary
                if asr_for_apply:
                    source_cues, n1 = apply_asr_glossary_to_cues(
                        source_cues, asr_for_apply, asr_only=True
                    )
                    gloss_hits += n1
                if glossary:
                    source_cues, n2 = apply_asr_glossary_to_cues(
                        source_cues, glossary, asr_only=False
                    )
                    gloss_hits += n2
                if gloss_hits > 0:
                    progress(
                        {
                            "stage": "cleanup",
                            "percent": 89,
                            "detail": f"ASR 术语修正 · {gloss_hits} 处",
                        }
                    )
                    for w in stream_writers:
                        try:
                            w.replace_all(source_cues)
                        except Exception:
                            pass
            except Exception:
                pass

            # Glue particle / stub cues before MT (JA soft-AV + film EN monologues)
            try:
                lang_l = str(language or "").lower()
                film_mode = bool(vad_opts.get("filmPreset"))
                is_en = lang_l.startswith("en") or lang_l in ("english",)
                if (
                    (
                        lang_l.startswith("ja")
                        or lang_l in ("japanese", "jp")
                        or ja_av
                        or film_mode
                        or is_en
                    )
                    and task in ("translate_mt", "dual", "transcribe")
                ):
                    from .quality import merge_short_neighbor_cues

                    before_short = len(source_cues or [])
                    source_cues = merge_short_neighbor_cues(
                        source_cues,
                        max_gap_s=0.85 if (film_mode or is_en) else 0.55,
                        max_merged_duration_s=8.0 if (film_mode or is_en) else 7.0,
                    )
                    short_merged = max(0, before_short - len(source_cues or []))
                    if short_merged > 0:
                        progress(
                            {
                                "stage": "cleanup",
                                "percent": 89,
                                "detail": f"短句合并 · {short_merged}",
                            }
                        )
                        for w in stream_writers:
                            try:
                                w.replace_all(source_cues)
                            except Exception:
                                pass
            except Exception:
                pass

            # Whisper JA name/filler loops (玲奈玲奈 / 葵葵葵) before MT / export
            try:
                from .asr_name_loops import strip_asr_name_loops_in_cues

                before_loop = len(source_cues or [])
                source_cues, loop_changed = strip_asr_name_loops_in_cues(source_cues)
                dropped_empty = max(0, before_loop - len(source_cues or []))
                if loop_changed or dropped_empty:
                    bits = []
                    if loop_changed:
                        bits.append(f"叠名 {loop_changed}")
                    if dropped_empty:
                        bits.append(f"空句 {dropped_empty}")
                    progress(
                        {
                            "stage": "cleanup",
                            "percent": 89,
                            "detail": "ASR 叠名清理 · " + " · ".join(bits),
                        }
                    )
                    for w in stream_writers:
                        try:
                            w.replace_all(source_cues)
                        except Exception:
                            pass
            except Exception:
                pass
        finally:
            if job:
                try:
                    job.kill_subprocesses(reason="job_cleanup")
                except Exception:
                    pass
            cleanup_temps(temps)
            try:
                sweep_job_temps()
            except Exception:
                pass

    if job and job.cancelled:
        raise JobCancelled()

    if job and source_cues:
        try:
            from .checkpoint import STAGE_ASR_DONE, save_checkpoint

            save_checkpoint(
                job.id,
                stage=STAGE_ASR_DONE,
                request=request,
                source_cues=source_cues,
            )
        except Exception:
            pass

    stem = Path(media).stem
    outputs: list[dict[str, Any]] = []
    result_cues: dict[str, Any] = {"source": source_cues}

    if task == "transcribe":
        for fmt in formats:
            path = write_subtitle(source_cues, output_dir / f"{stem}.{fmt}", fmt=fmt)
            outputs.append({"role": "source", "path": str(path), "format": fmt})
        if include_words:
            from .batch import write_words_json

            wpath = write_words_json(source_cues, output_dir / f"{stem}.words.json")
            outputs.append({"role": "words", "path": str(wpath), "format": "words-json"})
        if karaoke_vtt:
            from .subtitles import write_karaoke_vtt

            kpath = write_karaoke_vtt(source_cues, output_dir / f"{stem}.karaoke.vtt")
            outputs.append({"role": "karaoke", "path": str(kpath), "format": "vtt-karaoke"})
        progress({"stage": "done", "percent": 100, "detail": "转写完成"})
        if job:
            try:
                from .checkpoint import delete_checkpoint

                delete_checkpoint(job.id)
            except Exception:
                pass
        if release_gpu_after:
            try:
                from .runtime_release import release_gpu_memory

                release_gpu_memory(reason="job_done", unload_models=True)
            except Exception:
                pass
        out = {"task": task, "cues": result_cues, "outputs": outputs}
        return out

    if task == "dual":
        for fmt in formats:
            src_path = write_subtitle(source_cues, output_dir / f"{stem}.src.{fmt}", fmt=fmt)
            outputs.append({"role": "source", "path": str(src_path), "format": fmt})
    elif task == "translate_mt":
        for fmt in formats:
            write_subtitle(source_cues, output_dir / f"{stem}.src.partial.{fmt}", fmt=fmt)

    mt_id = None
    mt_lang = _guess_mt_language(language, source_cues)
    if can_skip_mt:
        progress(
            {
                "stage": "translate",
                "percent": 92,
                "detail": f"从断点恢复译文（{len(resume_zh or [])} 条）",
            }
        )
        zh_cues = [dict(c) for c in (resume_zh or []) if isinstance(c, dict)]
    else:
        try:
            from .runtime_release import release_gpu_memory
            import time as _time

            # External LLM (e.g. Sakura / llama-server) needs VRAM; unload local models.
            release_gpu_memory(
                reason="pre_mt",
                unload_models=(mt_backend == BACKEND_EXTERNAL),
            )
            # After long Torch ASR (Qwen), give the NVIDIA driver a moment before
            # Electron spawns llama-server against the same GPU.
            if mt_backend == BACKEND_EXTERNAL:
                _time.sleep(1.2)
        except Exception:
            pass

        if _is_chinese_lang(mt_lang):
            progress(
                {
                    "stage": "translate",
                    "percent": 90,
                    "detail": "源语言已是中文，跳过机器翻译",
                }
            )
            zh_cues = [
                {
                    "start": c.get("start"),
                    "end": c.get("end"),
                    "text": str(c.get("text") or ""),
                }
                for c in (source_cues or [])
            ]
        else:
            from .glossary import (
                apply_glossary_to_cues,
                collect_ja_cast_names,
                enforce_glossary_on_cues,
                mt_name_lock_entries,
                restore_glossary_on_cues,
            )

            # Built-in JA→ZH name lexicon + cast identity lock (舞≠舞蹈)
            mt_glossary = glossary
            try:
                from .mt.ja_names import merge_name_glossary

                if str(mt_lang or language or "").lower().startswith("ja"):
                    # opt-out: "builtinNames": false
                    if request.get("builtinNames", request.get("builtin_names", True)):
                        mt_glossary = merge_name_glossary(mt_glossary)
                lock_names = collect_ja_cast_names(
                    asr_glossary, cast_names, asr_only=True
                )
                lock_rows = mt_name_lock_entries(lock_names)
                if lock_rows:
                    if isinstance(mt_glossary, list):
                        mt_glossary = list(mt_glossary) + lock_rows
                    elif mt_glossary:
                        mt_glossary = [mt_glossary, *lock_rows]
                    else:
                        mt_glossary = lock_rows
            except Exception:
                mt_glossary = glossary

            mt_input, gloss_maps = apply_glossary_to_cues(source_cues, mt_glossary)
            if mt_backend == BACKEND_EXTERNAL:
                mt_id = "external"
            else:
                mt_id = pick_mt_model(mt_lang, str(mt_model).strip() if mt_model else None)

            def _mt_cancel_check() -> None:
                if job and job.cancelled:
                    raise JobCancelled()

            def _promote_src_partials() -> list[str]:
                """Keep ASR output when MT fails mid translate_mt job."""
                kept: list[str] = []
                if task != "translate_mt":
                    return kept
                stem_local = Path(media).stem
                for fmt in formats:
                    partial = output_dir / f"{stem_local}.src.partial.{fmt}"
                    final = output_dir / f"{stem_local}.src.{fmt}"
                    try:
                        if partial.is_file():
                            if final.exists():
                                final.unlink()
                            partial.replace(final)
                            kept.append(str(final))
                    except OSError:
                        if partial.is_file():
                            kept.append(str(partial))
                return kept

            try:
                zh_cues = translate_cues(
                    mt_input,
                    language=mt_lang,
                    mt_model=mt_id if mt_backend != BACKEND_EXTERNAL else None,
                    device=device,
                    mt_backend=mt_backend,
                    mt_external=mt_external if isinstance(mt_external, dict) else None,
                    job_id=job.id if job else None,
                    on_progress=lambda e: progress(e),
                    cancel_check=_mt_cancel_check,
                )
            except Exception as mt_err:
                if _is_cancel_message(mt_err) or isinstance(mt_err, JobCancelled):
                    raise
                kept_paths = _promote_src_partials()
                hint = (
                    f" 原文已保留：{', '.join(kept_paths)}"
                    if kept_paths
                    else ""
                )
                raise RuntimeError(f"{mt_err}{hint}") from mt_err
            zh_cues = restore_glossary_on_cues(zh_cues, gloss_maps)
            zh_cues = enforce_glossary_on_cues(source_cues, zh_cues, mt_glossary)
            # Opus-oriented JA polish; skip for external LLM backends.
            if mt_backend != BACKEND_EXTERNAL and (
                str(mt_lang or language or "").lower().startswith("ja")
                or str(mt_lang or language or "").lower() in ("japanese", "jp")
            ):
                try:
                    from .mt.ja_polish import polish_zh_cues_after_glossary

                    zh_cues = polish_zh_cues_after_glossary(source_cues, zh_cues)
                except Exception:
                    pass

        if job:
            try:
                from .checkpoint import STAGE_MT_DONE, save_checkpoint

                save_checkpoint(
                    job.id,
                    stage=STAGE_MT_DONE,
                    request=request,
                    source_cues=source_cues,
                    zh_cues=zh_cues,
                    extra={"mtModel": mt_id, "language": mt_lang},
                )
            except Exception:
                pass

    result_cues["zh"] = zh_cues

    if task == "translate_mt":
        # Same basename as the media file so players auto-load (e.g. Movie.srt next to Movie.mkv).
        for fmt in formats:
            path = write_subtitle(zh_cues, output_dir / f"{stem}.{fmt}", fmt=fmt)
            outputs.append({"role": "zh", "path": str(path), "format": fmt})
            try:
                (output_dir / f"{stem}.src.partial.{fmt}").unlink(missing_ok=True)  # type: ignore[arg-type]
            except TypeError:
                partial = output_dir / f"{stem}.src.partial.{fmt}"
                if partial.exists():
                    partial.unlink()
            except Exception:
                pass
        if include_words:
            from .batch import write_words_json

            wpath = write_words_json(source_cues, output_dir / f"{stem}.words.json")
            outputs.append({"role": "words", "path": str(wpath), "format": "words-json"})
    elif task == "dual":
        for fmt in formats:
            zh_path = write_subtitle(zh_cues, output_dir / f"{stem}.zh.{fmt}", fmt=fmt)
            outputs.append({"role": "zh", "path": str(zh_path), "format": fmt})
        if want_dual_ass:
            from .subtitles import write_ass_dual

            dual_line_order = (
                request.get("dualLineOrder")
                or request.get("dual_line_order")
                or request.get("lineOrder")
            )
            dual_path = write_ass_dual(
                source_cues,
                zh_cues,
                output_dir / f"{stem}.dual.ass",
                line_order=str(dual_line_order) if dual_line_order is not None else None,
            )
            outputs.append({"role": "dual", "path": str(dual_path), "format": "ass-dual"})
        if include_words:
            from .batch import write_words_json

            wpath = write_words_json(source_cues, output_dir / f"{stem}.words.json")
            outputs.append({"role": "words", "path": str(wpath), "format": "words-json"})
    else:
        raise ValueError(f"unsupported task: {task}")

    if karaoke_vtt and task in ("translate_mt", "dual"):
        from .subtitles import write_karaoke_vtt

        kpath = write_karaoke_vtt(source_cues, output_dir / f"{stem}.karaoke.vtt")
        outputs.append({"role": "karaoke", "path": str(kpath), "format": "vtt-karaoke"})

    _done_zh = {
        "translate_mt": "翻译完成",
        "dual": "双语完成",
        "transcribe": "转写完成",
    }.get(str(task or ""), "完成")
    progress({"stage": "done", "percent": 100, "detail": _done_zh})
    if job:
        try:
            from .checkpoint import delete_checkpoint

            delete_checkpoint(job.id)
        except Exception:
            pass
    if release_gpu_after:
        try:
            from .runtime_release import release_gpu_memory

            release_gpu_memory(reason="job_done", unload_models=True)
        except Exception:
            pass
    return {
        "task": task,
        "cues": result_cues,
        "outputs": outputs,
        "mtModel": mt_id,
        "language": mt_lang,
    }


JOBS = JobManager(max_concurrent=_default_max_concurrent_jobs())
